package com.arjunren.bus;
import java.math.BigDecimal;import java.sql.*;import java.time.OffsetDateTime;import java.util.UUID;
public final class BookingService{private final Database db;public BookingService(Database db){this.db=db;}public Booking reserve(long userId,long tripId,int seat){if(seat<1)throw new IllegalArgumentException("Seat must be positive");try(var c=db.connection()){c.setAutoCommit(false);try(var q=c.prepareStatement("SELECT b.capacity,r.base_fare,t.departure_at,t.status FROM trips t JOIN buses b ON b.id=t.bus_id JOIN routes r ON r.id=t.route_id WHERE t.id=? FOR UPDATE")){q.setLong(1,tripId);try(var r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException("Trip not found");if(seat>r.getInt(1))throw new IllegalArgumentException("Seat exceeds bus capacity");if(!"SCHEDULED".equals(r.getString(4))||r.getObject(3,OffsetDateTime.class).isBefore(OffsetDateTime.now()))throw new IllegalStateException("Trip is unavailable");var ref="BUS-"+UUID.randomUUID().toString().replace("-","").substring(0,10).toUpperCase();try(var i=c.prepareStatement("INSERT INTO bookings(reference,trip_id,user_id,seat_number,fare) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){i.setString(1,ref);i.setLong(2,tripId);i.setLong(3,userId);i.setInt(4,seat);i.setBigDecimal(5,r.getBigDecimal(2));i.executeUpdate();try(var k=i.getGeneratedKeys()){k.next();c.commit();return new Booking(k.getLong(1),ref,tripId,userId,seat,"BOOKED",r.getBigDecimal(2));}}}}catch(SQLException e){c.rollback();if("23505".equals(e.getSQLState()))throw new IllegalStateException("Seat is already booked");throw e;}}catch(SQLException e){throw new IllegalStateException(e);}}public void cancel(long bookingId,long userId,boolean admin){try(var c=db.connection();var s=c.prepareStatement("UPDATE bookings SET status='CANCELLED' WHERE id=? AND status='BOOKED' AND (user_id=? OR ?=TRUE)")){s.setLong(1,bookingId);s.setLong(2,userId);s.setBoolean(3,admin);if(s.executeUpdate()==0)throw new IllegalStateException("Booking cannot be cancelled");}catch(SQLException e){throw new IllegalStateException(e);}}public record Booking(long id,String reference,long tripId,long userId,int seatNumber,String status,BigDecimal fare){}}
